use vstd::prelude::*;

verus! {
    spec fn array_eq(arr: &[bool; 10], vec: &Vec<bool>) -> bool {
        // Check that the vector has length 10 and matches array element-wise
        vec.len() == 10 &&
        forall(|k: int| (0 <= k && k < 10) ==> vec.index(k as usize) == arr[k as usize])
    }

    fn array_to_sequence(arr: &[bool; 10]) -> (res: Vec<bool>)
        ensures
            array_eq(arr, &res),
    {
        let mut res: Vec<bool> = Vec::new();
        let mut i: usize = 0;
        while i < 10
            invariant
                i <= 10,
                res.len() == i,
                forall(|k: int| (0 <= k && k < (i as int)) ==> res.index(k as usize) == arr[k as usize])
            decreases 10 - i,
        {
            res.push(arr[i]);
            i += 1;
        }
        res
    }
}
